<?php
require_once __DIR__ . '/../../config/config.php'; require_once __DIR__ . '/../../includes/functions.php';
$transactions = mysqli_query($conn, 'SELECT t.kode_transaksi, t.tanggal_transaksi, t.no_order, t.total, t.QRIS, t.tunai, t.kembalian, p.nama_produk, k.nama_kasir, d.nama_donasi FROM tabel_transaksi t INNER JOIN tabel_detail_transaksi dt ON dt.kode_transaksi = t.kode_transaksi INNER JOIN tabel_produk p ON p.id_produk = dt.id_produk INNER JOIN tabel_kasir k ON k.id_kasir = dt.id_kasir LEFT JOIN tabel_donasi d ON d.id_donasi = t.id_donasi ORDER BY t.tanggal_transaksi DESC, t.no_order DESC');
require_once __DIR__ . '/../../includes/header.php';
?>
<section class="page-heading"><div><h2>Riwayat Transaksi</h2><p>Seluruh transaksi yang sudah tersimpan.</p></div><a class="button" href="<?= e(app_url('pages/transactions/add.php')) ?>">Transaksi Baru</a></section>
<?php if (mysqli_num_rows($transactions) === 0): ?><p class="alert">Belum ada transaksi.</p><?php else: ?><div class="table-wrapper"><table><thead><tr><th>Kode</th><th>Tanggal</th><th>Kasir</th><th>Produk</th><th>Total</th><th>Pembayaran</th><th>Aksi</th></tr></thead><tbody><?php while ($transaction = mysqli_fetch_assoc($transactions)): ?><tr><td><?= e($transaction['kode_transaksi']) ?></td><td><?= e(date('d-m-Y H:i', strtotime($transaction['tanggal_transaksi']))) ?></td><td><?= e($transaction['nama_kasir']) ?></td><td><?= e($transaction['nama_produk']) ?></td><td><?= e(format_rupiah((float) $transaction['total'])) ?></td><td><?= (float) $transaction['QRIS'] > 0 ? 'QRIS' : 'Tunai' ?></td><td><a class="button button-secondary" href="<?= e(app_url('pages/transactions/transaction_details.php?kode=' . rawurlencode($transaction['kode_transaksi']))) ?>">Detail</a></td></tr><?php endwhile; ?></tbody></table></div><?php endif; mysqli_free_result($transactions); require_once __DIR__ . '/../../includes/footer.php'; ?>
